-- Fictional catalog only. Existing records with these slugs are preserved.

select 'A very happy birthday','demo-birthday-type','A very happy birthday: a fictional typography birthday design with its own composition and editable words. ',o.id,g.id,'published','free',null,'EUR',true,true,0,'Typography'
from public.occasions o,public.categories g where o.slug='demo-birthday' and g.slug='demo-minimal' on conflict(slug) do nothing;
select id,'demo-birthday-type','{"design_key":"birthday-type","canvas":{"width":600,"height":800},"regions":[{"field":"recipient_name","role":"recipient"},{"field":"main_headline","role":"dynamic"},{"field":"custom_message","role":"body"},{"field":"sender_name","role":"signature"}],"artwork":{"type":"original-svg","key":"birthday-type"},"photo_upload":false}'::jsonb,'{"design_key":"birthday-type"}'::jsonb from public.cards where slug='demo-birthday-type' on conflict(card_id) do nothing;

